	private SlotManager slotManager;

	@Inject
	private SlotRegistry slotRegistry;

	@Inject
	private HideOrbRegistry orbRegistry;

	@Inject
	private EditManager editManager;

	@Inject
	private DragListener dragListener;

	@Inject
	private DragState dragState;

	@Inject
	private MouseManager mouseManager;

    private volatile int lifecycleGeneration;

    private void later(Runnable task)
    {
        if (!manager.active) return;
        final int generation = lifecycleGeneration;
        clientThread.invokeLater(() -> {
            if (manager.active && generation == lifecycleGeneration) task.run();
        });
    }

	protected void startUp() throws Exception
	{
        final int generation = ++lifecycleGeneration;
		legacyConfigs.importOnce();
        manager.migrateConfigs();
		overlayManager.add(minimapOverlay);
        overlayManager.add(interfaceEditor);
        eventBus.register(gameframe);
        mouseManager.registerMouseListener(0, interfaceEditor);
		keyManager.registerKeyListener(this);
		mouseManager.registerMouseListener(dragListener);
		orbRegistry.registerAll();

		if (!manager.isLoggedIn())
		{
			manager.isLoggingIn = true;
		}

		manager.active = true;
        manager.isUpdatingProfile = false;
		manager.isEditingLayout = false;
		manager.hideWorldMap = config.hideWorld();
		manager.hideLogoutX = config.hideLogout();
		manager.enableNoClickThrough = config.enableNoClickthrough();
		manager.enableOrbSwapping = config.layout() != OrbLayout.FREE_POSITION && config.enableOrbSwapping();
		manager.snapCornerRepositioned = manager.isSnapCornerRepositioned();

		clientThread.invoke(() ->
		{
            if (!manager.active || generation != lifecycleGeneration) return;
			slotManager.init();

			if (manager.isLoggedIn())
			{
				manager.update(Script.FORCE_UPDATE);
				manager.hideAllOrbsByConfig();
				manager.setupMinimapOverlay();
				manager.hideMinimapOnTabClose(config.hideMinimapWithSidePanel());
			}
		gameframe.start();
            if (config.editInterface()) editManager.toggleEditMode(true);
        });
	}

	protected void shutDown() throws Exception
	{
        lifecycleGeneration++;
        manager.active = false;
		overlayManager.remove(minimapOverlay);
        overlayManager.remove(interfaceEditor);
        eventBus.unregister(gameframe);
        mouseManager.unregisterMouseListener(interfaceEditor);
		keyManager.unregisterKeyListener(this);
		mouseManager.unregisterMouseListener(dragListener);
		clientThread.invoke(() -> { gameframe.stop(); manager.reset(); });
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		//don't check for drag events unless layout editing is enabled
		if (!manager.isEditingLayout)
		{
			return;
		}

		//gated by client.getDraggedWidget(), with actual changes only if the dragged widget is expected
		dragListener.updateDrag();

		//onWidgetDrag works, but is finicky
		//ex: moving a widget to 0,0 in bounds, then release the mouse to stop the drag (position updated)
		//grab and drag the same widget, with it's ending position the same as it was before (no change)
		//onWidgetDrag event will not fire -> which would potentially leave things stale (indicators/position)
		//TODO - still unsure if it's just the implementation...
		if (client.getMouseCurrentButton() == 0 && dragState.wasDragging)
		{
			dragListener.finalizeDrag();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.HOPPING ||
			event.getGameState() == GameState.LOGIN_SCREEN ||
			event.getGameState() == GameState.LOGGING_IN)
		{
			manager.isLoggingIn = true;
			manager.wikiPluginBannerExists = false;
			manager.clearCustomChildren();
		}
		else if (manager.isLoggedIn() && manager.isLoggingIn)
		{
			manager.isLoggingIn = false;
			manager.createCustomChildren();
		}
	}

	@Subscribe(priority = -1.0f)
	public void onScriptPostFired(ScriptPostFired event)
	{
		int scriptId = event.getScriptId();

		//prevent unwanted changes while in edit-mode
		if (config.layout() != OrbLayout.FREE_POSITION && manager.isEditingLayout &&
			(scriptId == Script.TOPLEVEL_REDRAW ||
				scriptId == Script.PROC_TOPLEVEL_SUBCHANGE ||
				scriptId == Script.TOPLEVEL_SIDE_CUSTOMIZE ||
				scriptId == Script.WIKI_ICON_INIT ||
				scriptId == Script.WORLD_MAP_UPDATE ||
				scriptId == Script.WIKI_ICON_UPDATE ||
				scriptId == Script.ORBS_UPDATE_STORE ||
				scriptId == Script.ORBS_UPDATE_ACTIVITY))
		{
			widgetManager.remapTargets(
				Orbs.WIKI_ICON_CONTAINER,
				Orbs.STORE_ORB_CONTAINER,
				Orbs.ACTIVITY_ORB_CONTAINER);

			widgetManager.setTargetsHidden(false, Compass.values());
			if (manager.isCompactLayout())
			{
				if (manager.compassFrame != null)
				{
					manager.compassFrame.setHidden(false);
				}
			}
			return;
		}

		switch (scriptId)
		{
			case Script.GRAPHIC_SWAPPER:
				manager.resolveOrbFrameMismatch();
				break;

			case Script.TOPLEVEL_SUBCHANGE:
				//ideally for display mode change
				if (manager.isEditingLayout)
				{
					editManager.toggleEditMode(false);
				}
				break;

			case Script.TOPLEVEL_REDRAW:
			case Script.TOPLEVEL_RESIZE_CUSTOMIZE:
			case Script.PROC_TOPLEVEL_SUBCHANGE:
			case Script.TOPLEVEL_SIDE_CUSTOMIZE:
				manager.hideLogout();
				manager.updateLogoutXOverlay();
				manager.hideMinimapOnTabClose(config.hideMinimapWithSidePanel());
				break;

			case Script.ORBS_UPDATE_SPECENERGY:
				if (config.layout() != OrbLayout.FREE_POSITION && manager.isEditingLayout && config.hideSpec())
				{
					//prevent the script from setting the opacity back to 25
					widgetManager.setTargetOpacity(Orbs.SPEC_ORB_CONTAINER, EDIT_MODE_HIDDEN_OPACITY);
				}
			case Script.ORBS_UPDATE_HEALTH:
				if (!manager.isCompactLayout())
				{
					manager.updateNoClickThrough();
				}
				break;

			case Script.WORLD_MAP_UPDATE:
				if (manager.hideWorldMap)
				{
					widgetManager.remapTargets(Orbs.WORLD_MAP_CONTAINER);
					return;
				}
			case Script.ORBS_UPDATE_STORE:
			case Script.ORBS_UPDATE_ACTIVITY:
			case Script.WIKI_ICON_INIT:
			case Script.WIKI_ICON_UPDATE:
				//case Script.GRID_MASTER_ORB_UPDATE:
				if (!manager.isMinimapMinimized())
				{
					manager.update(scriptId);

					if (scriptId == Script.WIKI_ICON_INIT || scriptId == Script.WIKI_ICON_UPDATE)
					{
						manager.updateWikiBannerVisibility(config.hideWiki());
					}
				}
				break;
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		int scriptId = event.getScriptId();

		if (scriptId == Orbs.WORLD_MAP_TOOLTIP.getScriptId())
		{
			int id = client.getIntStack()[2];
			int tooltipId = Orbs.WORLD_MAP_TOOLTIP.getComponentId();
			if (id == tooltipId)
			{
				boolean hidden = manager.isCompactLayout() || manager.hideWorldMap;
				widgetManager.setHidden(tooltipId, hidden);
			}
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		switch (event.getVarbitId())
		{
			case Varbit.CUTSCENE_STATUS:
				manager.isCutsceneActive = manager.isCutsceneActive();
				break;

			case Varbit.MINIMAP_TOGGLE:
				widgetManager.remapTargets(Orbs.LOGOUT_X_ICON, Orbs.LOGOUT_X_STONE);
				manager.updateCustomChildren();
				manager.setupMinimapContainer(false);
				break;

			case Varbit.STORE_ORB_TOGGLE:
			case Varbit.ACTIVITY_ORB_TOGGLE:
				//might need to add other varbit triggers (toggle wiki, toggle data orbs?)
				if (manager.isEditingLayout)
				{
					editManager.toggleEditMode(false);
				}

				if (manager.allowReordering())
				{
					widgetManager.remapTargets(Orbs.values());

					if (config.minimapTogglePlacement() == TogglePlacement.BELOW_MAP)
					{
						manager.updateMinimapToggleButton();
					}
				}
				break;
		}
	}

	@Subscribe
	public void onVarClientIntChanged(VarClientIntChanged event)
	{
		if (event.getIndex() == VarClient.SIDE_PANEL_ID)
		{
			if (manager.isEditingLayout &&
				config.hideMinimapWithSidePanel() && manager.isSidePanelHidden())
			{
				editManager.toggleEditMode(false);
			}
		}
	}

	@Subscribe(priority = -1.0f)
	public void onWidgetLoaded(WidgetLoaded event)
	{
		int id = event.getGroupId();
		switch (id)
		{
			case Orb.UNIVERSE >> 16:
				manager.update(Script.FORCE_UPDATE);
				manager.hideAllOrbsByConfig();
				break;

			case Widgets.MinimapOverlay.UNIVERSE >> 16:
				manager.setupMinimapOverlay();
				break;
		}
	}

	@Subscribe(priority = -1.0f)
	public void onConfigChanged(ConfigChanged event)
	{
		String group = event.getGroup();
		String key = event.getKey();

		if (group.equals(ConfigGroup.Core.RUNELITE))
		{
			if (key.equals(ConfigKeys.Core.SNAPCORNER_PREFIX + OverlayPosition.CANVAS_TOP_RIGHT + ConfigKeys.Core.SNAPCORNER_CONFIG_LOCATION))
			{
				manager.snapCornerRepositioned = event.getNewValue() != null;
			}
		}

		if (group.equals(ConfigGroup.Core.MINIMAP))
		{
			if (key.equals(ConfigKeys.Core.HIDE_MINIMAP))
			{
				later(() -> manager.hideMinimapOnTabClose(config.hideMinimapWithSidePanel()));
			}
		}

		if (group.equals(ConfigGroup.Core.WIKI))
		{
			if (key.equals(ConfigKeys.Core.SHOW_WIKI_MINIMAP_BUTTON))
			{
				manager.warnWikiPluginConflict();
				later(() ->
				{
					if (manager.isEditingLayout)
					{
						editManager.toggleEditMode(false);
					}
					widgetManager.remapTargets(Orbs.WIKI_ICON_CONTAINER);
					manager.updateWikiBannerVisibility(config.hideWiki());
					manager.updateCustomChildren();
				});
			}
		}

		                if (group.equals(GROUP_NAME) && key.equals("resetLayoutPositions"))
        {
            if (config.resetLayoutPositions()) later(() -> {
                editManager.toggleEditMode(false);
                gameframe.resetPositions();
                configManager.setConfiguration(GROUP_NAME, "resetLayoutPositions", false);
            });
            return;
        }
if (group.equals(GROUP_NAME) && (key.startsWith("free_") || key.startsWith("menu") || key.startsWith("hideStone")
    || key.equals("hiddenStones") || key.equals("hideTopMenu") || key.equals("hideBottomMenu")
    || key.equals("hideLeftBar") || key.equals("hideRightBar") || key.equals("showMenuToggle") || key.equals("editGrid"))) return;
        if (group.equals(GROUP_NAME) && key.equals("editInterface"))
        {
            later(() -> editManager.toggleEditMode(config.editInterface()));
            return;
        }
if (!group.equals(GROUP_NAME))
		{
			return;
		}

		if (slotRegistry.isSwapConfig(key) || orbRegistry.isHideConfig(key))
		{
			if (config.layout() == OrbLayout.FREE_POSITION)
			{
				later(() -> { manager.hideOrbByConfig(key); gameframe.refresh(); });
				return;
			}
			if (!manager.isEditingLayout)
			{
				later(() ->
				{
					manager.hideOrbByConfig(key);

					if (!manager.isFixedMode())
					{
						manager.rebuildLayout();
					}
				});
			}
			else if (orbRegistry.isHideConfig(key)) later(() -> editManager.syncVisibility(key));
			return;
		}

		if (manager.isEditingLayout && !manager.isUpdatingProfile)
		{
			later(() ->
			{
				if (!key.contains(manager.getCurrentPrefix()))
				{
					editManager.toggleEditMode(false);
				}
			});
		}

		switch (key)
		{
			case ConfigKeys.COMPASS:
				later(() ->
				{
					manager.setupMinimapContainer(false);
					widgetManager.setTargetsHidden(manager.isCompassHidden(), Compass.values());
					widgetManager.remapTargets(Compass.values());
					widgetManager.remapTargets(Orbs.values());
				});
				break;

			case ConfigKeys.MINIMAP_BUTTON_PLACEMENT:
			case ConfigKeys.ENABLE_OVERLAY_TOGGLE_OPTION:
				later(manager::updateMinimapToggleButton);
				break;

			case ConfigKeys.RIGHT_CLICK_TOGGLE_BUTTONS:
				later(manager::updateCustomChildren);
				break;

			case ConfigKeys.ENABLE_ORB_SWAPPING:
			case ConfigKeys.ENABLE_NO_CLICKTHROUGH:
				later(() ->
				{
					if (key.equals(ConfigKeys.ENABLE_NO_CLICKTHROUGH))
					{
						manager.enableNoClickThrough = config.enableNoClickthrough();
					}
					else
					{
						manager.enableOrbSwapping = config.layout() != OrbLayout.FREE_POSITION && config.enableOrbSwapping();
						slotManager.update();
						manager.rebuildLayout();
					}

					manager.updateNoClickThrough();

					if (!manager.isCompactLayout())
					{
						widgetManager.remapTargets(Orbs.XP_DROPS_CONTAINER);
					}
				});
				break;

			case ConfigKeys.ENABLE_MINIMAP_OVERLAY:
				later(() ->
				{
					widgetManager.setHidden(Widgets.MinimapOverlay.UNIVERSE, manager.hideMinimapOverlay());
					manager.hideLogout();
					manager.updateLogoutXPosition();
					manager.updateLogoutXOverlay();
				});
				break;

			case ConfigKeys.ENABLE_LOGOUT_X_OVERLAY:
				later(() ->
				{
					manager.hideLogout();
					manager.updateLogoutXPosition();
					manager.updateLogoutXOverlay();
				});
				break;

			case ConfigKeys.HIDE_MINIMAP_WITH_SIDE_PANEL:
				later(() -> manager.hideMinimapOnTabClose(config.hideMinimapWithSidePanel()));
				break;

			case ConfigKeys.ORB_LAYOUT:
			case ConfigKeys.MINIMAP:
			case ConfigKeys.VERTICAL_Y_ADJUSTMENT:
			case ConfigKeys.HORIZONTAL_ANCHOR:
			case ConfigKeys.VERTICAL_ANCHOR:
			case ConfigKeys.DISABLE_REORDERING:
			case ConfigKeys.LEAVE_EMPTY_SPACE:
				later(() ->
				{
					if (!manager.isFixedMode())
					{
						manager.rebuildLayout();
					}
				});
				break;
		}
	}

	public void resetConfiguration()
	{
		manager.isUpdatingProfile = true;
		clientThread.invoke(() -> { gameframe.resetPositions(); manager.rebuild(true); });
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		legacyConfigs.importOnce();
        manager.migrateConfigs();

		manager.isUpdatingProfile = true;
		clientThread.invoke(() -> manager.rebuild(false));
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		String name = event.getPlugin().getName().toLowerCase(Locale.ROOT);
		switch (name)
		{
			case ConfigGroup.Core.WIKI:
				later(() ->
				{
					if (manager.isEditingLayout)
					{
						editManager.toggleEditMode(false);
					}
					else
					{
						manager.rebuildLayout();
					}
					manager.updateWikiBannerVisibility(config.hideWiki());
				});
				break;

			case ConfigGroup.Core.MINIMAP:
				//keep minimap hidden when the core minimap plugin is toggled (somewhat edge case)
				later(() -> manager.hideMinimapOnTabClose(config.hideMinimapWithSidePanel()));
				break;
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		manager.addCustomMenuEntries(event.getMenuEntry());
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyPressed(KeyEvent e)
	{        if (config.showMenuToggle().matches(e))
        {
            e.consume();
            later(gameframe::toggleShown);
            return;
        }

		if (manager.isEditingLayout)
		{
			if (e.getKeyCode() == KeyEvent.VK_ESCAPE || config.hotkeyKeybind().matches(e))
			{
				if (e.getKeyCode() == KeyEvent.VK_ESCAPE)
				{
					e.consume();
				}
				later(() -> editManager.toggleEditMode(false));
			}
			return;
		}

		if (!config.hotkeyKeybind().matches(e))
		{
			return;
		}

		//during or after a cutscene, wait until the layout has settled before allowing toggles
		if (manager.isCutsceneActive)
		{
			return;
		}

		//let the hotkey toggle the minimap button in fixed mode if EDIT_MODE is not the selected option
		if (config.toggleOption() == HotkeyOptions.MINIMAP_BUTTON
			|| manager.isFixedMode() && config.toggleOption() != HotkeyOptions.EDIT_MODE)
		{
			manager.saveConfig(ConfigKeys.MINIMAP_TOGGLE_BUTTON, !config.hideMinimapToggle());
			return;
		}

		switch (config.toggleOption())
		{
			case MINIMAP:
				later(manager::onMinimapToggle);
				break;

			case DETACHED_MINIMAP:
				manager.saveConfig(ConfigKeys.ENABLE_MINIMAP_OVERLAY, !config.showMinimapInCompactView());
				break;

			case EDIT_MODE:
				later(() -> editManager.toggleEditMode(true));
				break;
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}
}

package com.interfacelayout.layout;

import com.interfacelayout.layout.orbs.OrbConstants.Script;
import com.interfacelayout.layout.orbs.OrbController;
import com.interfacelayout.layout.edit.InterfaceEditor;
import com.interfacelayout.layout.menu.MenuStoneController;
import com.interfacelayout.layout.orbs.FreePositionController;
import com.interfacelayout.util.WidgetBoundsExpander;
import com.interfacelayout.util.WidgetStateStore;
import com.interfacelayout.layout.orbs.widget.layout.edit.EditManager;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.GameState;
import net.runelite.api.Client;
import com.interfacelayout.util.NativeOrbStateStore;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.FocusChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;

/** Coordinates new native layout mutations around RuneScape's own layout scripts. */
@Singleton
public class GameframeCoordinator
{
    @Inject private WidgetStateStore states;
    @Inject private WidgetBoundsExpander expander;
    @Inject private MenuStoneController menu;
    @Inject private com.interfacelayout.layout.menu.MenuOverlayBridge menuOverlays;
    @Inject private FreePositionController free;
    @Inject private com.interfacelayout.layout.orbs.FreeOrbOverlayBridge freeOverlays;
    @Inject private InterfaceEditor editor;
    @Inject private EditManager compactEditor;
    @Inject private OrbController manager;
    @Inject private ClientThread clientThread;
    @Inject private Client client;
    @Inject private NativeOrbStateStore nativeStates;
    private boolean running;
    private int layoutDepth;
    private int visibilityDepth;
    private volatile boolean refreshPending;

    public void start() { running = true; editor.setRefresh(this::refresh); refresh(); menuOverlays.start(this::refresh); freeOverlays.start(this::refresh); }
    public void stop() { running = false; layoutDepth = 0; visibilityDepth = 0; editor.cancel(); freeOverlays.stop(); menuOverlays.stop(); restore(); menu.resetSession(); }
    private void restore() { menu.restoreBackgrounds(); states.restore(); expander.clear(); }
    public void prepareNativeLayout() { restore(); }
    public boolean isHiddenByGame(net.runelite.api.widgets.Widget widget)
    {
        return widget == null || nativeStates.isHiddenByGame(widget, states);
    }
    public void refresh()
    {
        if (!running || layoutDepth > 0) return;
        restore(); menu.apply(); free.apply(); menuOverlays.sync(); freeOverlays.sync();
    }
    public void toggleShown() { if (running) { menu.toggleShown(); refresh(); } }
    private synchronized void scheduleRefresh()
    {
        if (refreshPending) return;
        refreshPending = true;
        clientThread.invokeLater(() -> { refreshPending = false; refresh(); });
    }
    public void resetPositions()
    {
        editor.cancel(); free.resetAll(); freeOverlays.resetAll(); menu.resetAll(); menuOverlays.resetAll(); manager.resetSavedPositionConfigs();
        refresh();
    }
    private boolean layoutScript(int id)
    {
        return id == Script.TOPLEVEL_REDRAW || id == Script.TOPLEVEL_SUBCHANGE
            || id == Script.PROC_TOPLEVEL_SUBCHANGE || id == Script.TOPLEVEL_SIDE_CUSTOMIZE
            || id == Script.TOPLEVEL_RESIZE_CUSTOMIZE || id == Script.ORBS_UPDATE_STORE
            || id == Script.ORBS_UPDATE_ACTIVITY || id == Script.WORLD_MAP_UPDATE
            || id == Script.WIKI_ICON_INIT || id == Script.WIKI_ICON_UPDATE;
    }
    @Subscribe(priority = 2) public void onScriptPreFired(ScriptPreFired event)
    {
        if (running && visibilityScript(event.getScriptId()) && visibilityDepth++ == 0)
            nativeStates.restoreVisibility();
        if (running && layoutScript(event.getScriptId()))
        {
            if (layoutDepth++ == 0) restore();
        }
    }
    @Subscribe(priority = -2) public void onScriptPostFired(ScriptPostFired event)
    {
        if (running && visibilityScript(event.getScriptId()))
        {
            visibilityDepth = Math.max(0, visibilityDepth - 1);
            if (visibilityDepth == 0) manager.refreshVisibility();
        }
        if (layoutScript(event.getScriptId()))
        {
            layoutDepth = Math.max(0, layoutDepth - 1);
            if (event.getScriptId() == Script.TOPLEVEL_SUBCHANGE) editor.cancel();
            refresh();
        }
    }
    @Subscribe(priority = -2) public void onWidgetLoaded(WidgetLoaded event)
    {
        // Native instances may have been replaced: cancel any handle drag before remapping.
        editor.cancel();
        states.discardRetired(client);
        nativeStates.discardRetired(client);
        refresh();
    }
    @Subscribe(priority = -2) public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN)
        {
            editor.cancel();
            if (manager.isEditingLayout) compactEditor.toggleEditMode(false);
            restore();
            layoutDepth = 0;
            visibilityDepth = 0;
        }
        else refresh();
    }
    private boolean visibilityScript(int id)
    {
        return layoutScript(id) || id == Script.ORBS_UPDATE_HEALTH
            || id == Script.ORBS_UPDATE_SPECENERGY || id == Script.TOPLEVEL_COMPASS_SETOPS;
    }
    @Subscribe(priority = -2) public void onConfigChanged(ConfigChanged event)
    {
        if (!event.getGroup().equals("interfacelayout")) return;
        if (event.getKey().equals("editInterface") || event.getKey().equals("menuLayout")
            || event.getKey().equals(com.interfacelayout.layout.orbs.OrbConstants.ConfigKeys.ORB_LAYOUT))
            editor.cancel();
        scheduleRefresh();
    }
    @Subscribe public void onFocusChanged(FocusChanged event)
    {
        // The mouse release may occur outside the client. Invalidate queued moves
        // rather than allowing a stale drag to resume when focus returns.
        if (running && !event.isFocused()) editor.cancel();
    }
    @Subscribe(priority = -2) public void onProfileChanged(ProfileChanged event)
    {
        editor.cancel(); menu.resetSession();
        scheduleRefresh();
    }
}

package com.interfacelayout.layout.edit;

import com.interfacelayout.layout.orbs.OrbController;
import com.interfacelayout.InterfaceLayoutConfig;
import com.interfacelayout.layout.menu.MenuStoneController;
import com.interfacelayout.layout.orbs.FreePositionController;
import com.interfacelayout.layout.orbs.widget.TargetWidget;
import com.interfacelayout.util.LayoutGeometry;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Overlay is an editing indicator only; all gameplay controls remain native widgets. */
@Singleton
public class InterfaceEditor extends Overlay implements MouseListener
{
    @Inject private OrbController manager;
    @Inject private InterfaceLayoutConfig config;
    @Inject private MenuStoneController menu;
    @Inject private com.interfacelayout.layout.menu.MenuOverlayBridge menuOverlays;
    @Inject private FreePositionController orbs;
    @Inject private ClientThread clientThread;
    private volatile List<Handle> handles = List.of();
    private volatile Handle dragged;
    private Point grab;
    private boolean detached;
    private volatile int generation;
    private Runnable refresh = () -> {};

    public void setRefresh(Runnable refresh) { this.refresh = refresh; }

    public InterfaceEditor()
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }
    public void cancel()
    {
        generation++;
        dragged = null; handles = List.of();
    }
    @Override public Dimension render(Graphics2D graphics)
    {
        List<Handle> current = new ArrayList<>();
        if (manager.isEditingLayout) orbs.bounds().forEach((target, bounds) -> current.add(new Handle(target, bounds)));
        menu.groups().forEach((id, bounds) -> current.add(new Handle(null, bounds, id, -1)));
        if (menu.individualDragging()) menu.stones().forEach((id, bounds) -> current.add(new Handle(null, bounds, -1, id)));
        handles = List.copyOf(current);
        if (!manager.isEditingLayout) return null;
        graphics.setColor(new Color(70, 220, 255));
        for (Handle handle : current)
        {
            if (handle.stone >= 0) continue;
            graphics.draw(handle.bounds);
            graphics.drawString(handle.target == null ? "Alt-drag bar; Shift-drag stone" : "Alt-drag " + handle.target,
                handle.bounds.x, Math.max(12, handle.bounds.y));
        }
        handles = List.copyOf(current);
        return null;
    }
    @Override public MouseEvent mousePressed(MouseEvent event)
    {
        // Whole bars and free orbs always use RuneLite's configured drag hotkey.
        // This listener owns only the Shift gesture for changing stone membership.
        if (!event.isShiftDown() || !menu.individualDragging()
            || (event.getButton() != MouseEvent.BUTTON1 && event.getButton() != MouseEvent.BUTTON3)) return event;
        List<Handle> current = handles;
        for (int i = current.size() - 1; i >= 0; i--)
        {
            Handle handle = current.get(i);
            if (handle.stone < 0) continue;
            if (!handle.bounds.contains(event.getPoint())) continue;
            if (event.getButton() == MouseEvent.BUTTON3)
            {
                int epoch = generation;
                clientThread.invokeLater(() -> {
                    if (generation != epoch) return;
                    menu.reattach(handle.stone);
                    refresh.run();
                });
                event.consume(); return event;
            }
            dragged = handle;
            detached = false;
            grab = new Point(event.getX() - handle.bounds.x, event.getY() - handle.bounds.y);
            event.consume(); break;
        }
        return event;
    }
    @Override public MouseEvent mouseDragged(MouseEvent event)
    {
        Handle handle = dragged;
        if (handle == null) return event;
        Point point = LayoutGeometry.snap(new Point(event.getX() - grab.x, event.getY() - grab.y), config.editGrid());
        int epoch = generation;
        boolean detachNow = handle.stone >= 0 && !detached;
        if (detachNow) detached = true;
        clientThread.invokeLater(() -> {
            if (generation != epoch) return;
            if (detachNow) menu.detach(handle.stone, point);
            else menu.moveStone(handle.stone, point);
            refresh.run();
            menuOverlays.moveGroupingStone(menu.groupForStone(handle.stone), point, detachNow);
        });
        event.consume(); return event;
    }
    @Override public MouseEvent mouseReleased(MouseEvent event)
    {
        Handle handle = dragged;
        if (handle != null)
        {
            if (handle.stone >= 0 && detached)
            {
                int epoch = generation;
                Point cursor = event.getPoint();
                clientThread.invokeLater(() -> {
                    if (generation != epoch) return;
                    menuOverlays.finishGroupingStone(menu.groupForStone(handle.stone));
                    menu.dropStone(handle.stone, cursor); refresh.run();
                });
            }
            dragged = null; event.consume();
        }
        return event;
    }
    @Override public MouseEvent mouseClicked(MouseEvent event) { return event; }
    @Override public MouseEvent mouseEntered(MouseEvent event) { return event; }
    @Override public MouseEvent mouseExited(MouseEvent event) { return event; }
    @Override public MouseEvent mouseMoved(MouseEvent event) { return event; }
    private static final class Handle
    {
        private final TargetWidget target;
        private final Rectangle bounds;
        private final int group, stone;
        Handle(TargetWidget target, Rectangle bounds) { this(target, bounds, -1, -1); }
        Handle(TargetWidget target, Rectangle bounds, int group, int stone)
        { this.target = target; this.bounds = new Rectangle(bounds); this.group = group; this.stone = stone; }
    }
}

package com.interfacelayout.layout.menu;

import com.interfacelayout.util.WidgetBoundsExpander;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Delegate whole-bar Alt dragging, origins and snapping to RuneLite's overlay renderer. */
@Singleton
public class MenuOverlayBridge
{
    @Inject private OverlayManager overlays;
    @Inject private MenuStoneController menu;
    @Inject private WidgetBoundsExpander expander;
    private final Map<String, GroupOverlay> groups = new HashMap<>();
    private final List<Overlay> nativeOverlays = new ArrayList<>();
    private Runnable refresh = () -> {};
    private boolean running;

    public void start(Runnable refresh) { this.refresh = refresh; running = true; sync(); }
    public void stop()
    {
        running = false;
        groups.values().forEach(overlay -> { overlay.getBounds().setSize(0, 0); overlays.remove(overlay); }); groups.clear();
        nativeOverlays.forEach(overlays::add); nativeOverlays.clear();
    }
    public void sync()
    {
        if (!running) return;
        // Retire old incarnations of numeric group slots. Keeping them registered
        // would accumulate invisible overlays after repeated detach/join gestures.
        String prefix = "INTERFACE_LAYOUT_MENU_" + menu.mode() + "_"
            + (menu.individualDragging() ? "group_" : "row_");
        groups.values().removeIf(overlay -> {
            if (!overlay.name.startsWith(prefix) || overlay.name.equals(name(overlay.id))) return false;
            overlay.getBounds().setSize(0, 0); overlays.remove(overlay); return true;
        });
        // Modern's two native row wrappers would otherwise force expanded parents
        // back to their old overlay origins. Retain and restore the exact objects.
        nativeOverlays.removeIf(overlay -> {
            if (replacesNativeOverlay(overlay.getName())) return false;
            overlays.add(overlay); return true;
        });
        overlays.removeIf(overlay -> {
            if (!replacesNativeOverlay(overlay.getName())) return false;
            // External anchor managers must not retain a phantom full-canvas slot
            // for a wrapper that no longer participates in the render pass.
            overlay.getBounds().setSize(0, 0);
            nativeOverlays.add(overlay); return true;
        });
        menu.groups().forEach((id, bounds) -> {
            String key = name(id);
            if (!groups.containsKey(key))
            {
                GroupOverlay overlay = new GroupOverlay(key, id);
                overlay.getBounds().setBounds(bounds);
                groups.put(key, overlay); overlays.add(overlay);
            }
            GroupOverlay overlay = groups.get(key);
            overlay.getBounds().setSize(bounds.getSize());
            if (overlay.getPreferredLocation() == null && overlay.getPreferredPosition() == null)
                overlay.getBounds().setLocation(bounds.getLocation());
        });
        groups.values().forEach(overlay -> {
            if (!overlay.name.equals(name(overlay.id)) || !menu.groups().containsKey(overlay.id))
                overlay.getBounds().setSize(0, 0);
        });
    }
    private boolean replacesNativeOverlay(String name)
    {
        // The native minimap wrappers measure the clipping container. When free
        // elements need canvas-wide clipping, that is no longer a draggable map
        // rectangle: rendering it also expands the green snap corner to canvas size.
        // Keep the exact wrapper and its preferences for restoration once native
        // clipping returns. Individual free elements have their own movement overlays.
        if (name.equals("RESIZABLE_MINIMAP_STONES_WIDGET"))
            return expander.isExpanded(InterfaceID.ToplevelOsrsStretch.MAP_CONTAINER);
        if (name.equals("RESIZABLE_MINIMAP_WIDGET"))
            return expander.isExpanded(InterfaceID.ToplevelPreEoc.MAP_CONTAINER);
        if (!menu.mode().equals("modern") || menu.groups().isEmpty()) return false;
        int row;
        if (name.equals("RESIZABLE_VIEWPORT_BOTTOM_LINE_TABS1")) row = 1;
        else if (name.equals("RESIZABLE_VIEWPORT_BOTTOM_LINE_TABS2")) row = 0;
        else return false;
        return menu.individualDragging() || menu.groups().containsKey(row);
    }
    private String name(int id)
    {
        return "INTERFACE_LAYOUT_MENU_" + menu.mode() + "_"
            + (menu.individualDragging() ? "group_" : "row_") + id
            + (menu.individualDragging() && menu.groupGeneration(id) > 0 ? "_" + menu.groupGeneration(id) : "");
    }
    public void moveGroupingStone(int id, Point canvas, boolean beginning)
    {
        GroupOverlay overlay = groups.get(name(id));
        if (overlay == null) return;
        if (beginning) clearPreference(id); // Normalize the origin once for this grouping gesture.
        overlay.setPreferredPosition(null);
        overlay.setPreferredLocation(new Point(canvas));
    }
    public void finishGroupingStone(int id)
    {
        GroupOverlay overlay = groups.get(name(id));
        if (overlay != null) overlays.saveOverlay(overlay);
    }
    public void clearPreference(int id)
    {
        GroupOverlay overlay = groups.get(name(id));
        if (overlay != null) { overlays.resetOverlay(overlay); overlay.lastApplied = null; overlay.reset = false; }
    }
    public void resetAll()
    {
        // Clear preferences for modes/groups not instantiated in this session too.
        for (String mode : new String[]{"fixed", "classic", "modern"})
            for (String kind : new String[]{"group_", "row_"})
                for (int id = 0; id <= 14; id++)
                {
                    overlays.resetOverlay(new GroupOverlay("INTERFACE_LAYOUT_MENU_" + mode + "_" + kind + id, id));
                    int version = menu.groupGeneration(mode, id);
                    if (kind.equals("group_") && version > 0)
                        overlays.resetOverlay(new GroupOverlay("INTERFACE_LAYOUT_MENU_" + mode + "_" + kind + id + "_" + version, id));
                }
        groups.values().forEach(overlay -> { overlays.resetOverlay(overlay); overlay.lastApplied = null; });
    }
    public final class GroupOverlay extends Overlay
    {
        private final String name;
        private final int id;
        private Point lastApplied;
        private boolean reset;
        GroupOverlay(String name, int id)
        {
            this.name = name; this.id = id;
            setPosition(OverlayPosition.DYNAMIC);
            setLayer(OverlayLayer.UNDER_WIDGETS);
            setPriority(Overlay.PRIORITY_HIGHEST);
            setMovable(true); setSnappable(true);
        }
        @Override public String getName() { return name; }
        @Override public void revalidate()
        {
            // RuneLite also revalidates overlays when their size/settings change.
            // Only an actual cleared preference represents an overlay reset.
            reset = getPreferredLocation() == null && getPreferredPosition() == null && lastApplied != null;
        }
        @Override public Dimension render(Graphics2D graphics)
        {
            Rectangle actual = menu.groups().get(id);
            if (!running || !name.equals(MenuOverlayBridge.this.name(id)) || actual == null) return null;
            if (reset && getPreferredLocation() == null && getPreferredPosition() == null)
            {
                reset = false; lastApplied = null; menu.resetGroup(id); refresh.run();
                actual = menu.groups().get(id);
                if (actual == null) return null;
            }
            reset = false;
            if (getPreferredLocation() != null || getPreferredPosition() != null)
            {
                // OverlayRenderer has already resolved origins, snapping and clamping.
                // Preferred locations are origin-relative, including negative offsets
                // from the right/bottom edge. Bounds are the resolved canvas position.
                Point position = getBounds().getLocation();
                if (!position.equals(lastApplied))
                {
                    lastApplied = new Point(position);
                    menu.saveGroup(id, position); refresh.run();
                }
            }
            else getBounds().setLocation(actual.getLocation());
            return actual.getSize();
        }
    }
}

package com.interfacelayout.layout.menu;

import com.interfacelayout.util.WidgetBoundsExpander;
import com.interfacelayout.util.WidgetGeometry;
import com.interfacelayout.util.WidgetStateStore;
import java.awt.Point;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

/** Split Modern's tiled row art into native tiles below the original buttons/icons. */
@Singleton
public class MenuStoneBackgrounds
{
    @Inject private Client client;
    @Inject private WidgetStateStore states;
    @Inject private WidgetBoundsExpander expander;
    private final Map<Widget, List<Widget>> owned = new IdentityHashMap<>();

    public void place(int index, Point destination, int width, int height)
    {
        place(index, destination, width, height, true);
    }

    public void place(int index, Point destination, int width, int height, boolean movable)
    {
        Widget background = prepareRow(index < 7, movable);
        if (background == null || background.isHidden()) return;
        List<Widget> children = owned.get(background);
        Widget tile = background.createChild(-1, WidgetType.GRAPHIC);
        children.add(tile);
        tile.setSpriteId(background.getSpriteId());
        tile.setSpriteTiling(true);
        tile.setOpacity(background.getOpacity());
        tile.setBorderType(background.getBorderType());
        tile.setNoClickThrough(false);
        tile.setOriginalWidth(width); tile.setOriginalHeight(height);
        Point parent = WidgetGeometry.location(background);
        tile.setOriginalX(destination.x - parent.x); tile.setOriginalY(destination.y - parent.y);
        tile.revalidate();
    }
    /** Remove the shared row art even when every stone in that row is hidden. */
    public Widget prepareRow(boolean top)
    {
        return prepareRow(top, true);
    }

    public Widget prepareRow(boolean top, boolean movable)
    {
        Widget background = client.getWidget(top ? InterfaceID.ToplevelPreEoc.SIDE_MOVABLE_BACKGROUND
            : InterfaceID.ToplevelPreEoc.SIDE_STATIC_BACKGROUND);
        if (background == null || background.isHidden()) return background;
        if (!owned.containsKey(background))
        {
            states.captureRendering(background);
            if (movable) expander.allowChildrenAcrossCanvas(background);
            background.setType(WidgetType.LAYER);
            owned.put(background, new ArrayList<>());
        }
        return background;
    }
    public void restore()
    {
        owned.forEach((parent, children) -> {
            Widget[] current = parent.getChildren();
            if (current == null) return;
            Widget[] remaining = current.clone();
            for (Widget child : children)
            {
                int index = child.getIndex();
                if (index >= 0 && index < remaining.length && remaining[index] == child) remaining[index] = null;
            }
            int length = remaining.length;
            while (length > 0 && remaining[length - 1] == null) length--;
            parent.setChildren(Arrays.copyOf(remaining, length));
        });
        owned.clear();
    }
}

