	private Widget getWidgetByDisplayMode(int fixed, int classic, int modern)
	{
		if (manager.isFixedMode())
		{
			return client.getWidget(fixed);
		}
		else
		{
			if (manager.isClassicResizable())
			{
				return client.getWidget(classic);
			}
			else
			{
				return client.getWidget(modern);
			}
		}
	}

	public void clearChild(Widget child)
	{
		if (child == null)
		{
			return;
		}

		Widget widget = child.getParent();
		if (widget == null)
		{
			return;
		}

		Widget[] children = widget.getChildren();
		if (children == null || children.length <= child.getIndex() || children[child.getIndex()] != child)
		{
			return;
		}

		children[child.getIndex()] = null;
	}

	public boolean isAttachedChild(Widget child)
	{
		if (child == null || child.getParent() == null || child.getIndex() < 0) return false;
		Widget[] children = child.getParent().getChildren();
		return children != null && child.getIndex() < children.length && children[child.getIndex()] == child;
	}

	public boolean hasChildren(Widget widget)
	{
		if (widget == null)
		{
			return false;
		}

		Widget[] children = widget.getChildren();
		return children != null && children.length > 0;
	}

