package com.interfacelayout.layout.orbs.widget.layout.offset.impl;

import com.interfacelayout.InterfaceLayoutConfig.TogglePlacement;
import com.interfacelayout.layout.orbs.OrbConstants.Layout;
import com.interfacelayout.layout.orbs.OrbController;
import com.interfacelayout.layout.orbs.widget.elements.Orbs;
import com.interfacelayout.layout.orbs.widget.layout.offset.OffsetTarget;
import com.interfacelayout.layout.orbs.widget.layout.slot.Slot;
import com.interfacelayout.layout.orbs.widget.layout.slot.SlotManager;
import lombok.Getter;

@Getter
public class MinimapButtonOffset implements OffsetTarget
{
	@Override
	public int xOffset(int x, boolean compactLayout, OrbController manager, SlotManager slotManager)
	{
		if (!compactLayout)
		{
			if (manager.isFixedMode())
			{
				return x;
			}

			x = manager.getTogglePlacement().getX();

			if (manager.allowReordering() && !manager.isEditingLayout)
			{
				if (manager.getTogglePlacement() == TogglePlacement.BELOW_MAP
					&& manager.isStoreHidden() && !manager.isStoreOrbDisabled())
				{
					x -= 33;
				}
			}

			return x;
		}

		if (manager.getCurrentLayout().isHorizontal())
		{
			if (manager.allowReordering() && !manager.isEditingLayout)
			{
				if (manager.isWikiHidden())
				{
					x -= 42;
				}
			}

			if (manager.isAnchorLeft())
			{
				int offset = slotManager.getHiddenSize();
				x -= offset;
			}
		}

		return x;
	}

	@Override
	public int yOffset(int y, boolean compactLayout, OrbController manager, SlotManager slotManager)
	{
		if (!compactLayout)
		{
			if (manager.isFixedMode())
			{
				return y;
			}

			y = manager.getTogglePlacement().getY();

			if (!manager.isEditingLayout)
			{
				//offset when store is hidden and minimap is visible
				if (manager.allowReordering() &&
					manager.getTogglePlacement() == TogglePlacement.BELOW_MAP
					&& manager.isStoreHidden() && !manager.isStoreOrbDisabled())
				{
					y -= 5;
				}

				if (manager.getTogglePlacement() == TogglePlacement.ABOVE_XP)
				{
					if (manager.shouldOffsetXpOrb())
					{
						y -= 2;
					}
				}
			}

			return y;
		}

		if (manager.getCurrentLayout().isVertical())
		{
			y = slotManager.applyHiddenYOffset(Orbs.WIKI_ICON_CONTAINER,
				Layout.Vertical.MAP_CONTAINER_HEIGHT - Layout.TOGGLE_BUTTON_SIZE);

			if (manager.allowReordering() && !manager.isEditingLayout)
			{
				if (manager.isAnchorTop())
				{
					if (manager.getCurrentLayout().isLastVisible(Slot.WIKI_SLOT, slotManager.getHiddenCountAbove()))
					{
						y += 4;
					}

					if (manager.isWikiHidden() && !manager.isClassicResizable() && !manager.hideLogoutX
						&& slotManager.getHiddenCountAbove() >= manager.getCurrentLayout().getGroup(Slot.WIKI_SLOT).indexOf(Slot.WIKI_SLOT))
					{
						y -= 14;
					}
				}
			}
		}

		return y;
	}
}

