package com.interfacelayout.layout.orbs.widget.layout.offset.impl;

import com.interfacelayout.layout.orbs.OrbController;
import com.interfacelayout.layout.orbs.widget.layout.offset.OffsetTarget;
import com.interfacelayout.layout.orbs.widget.layout.slot.SlotManager;
import lombok.Getter;

@Getter
public class OrbContainerOffset implements OffsetTarget
{
	private int offsetX;
	private int offsetY;
	private int offsetWidth;
	private int offsetHeight;

	@Override
	public int xOffset(int x, boolean compact, OrbController manager, SlotManager slotManager)
	{
		offsetX = x;

		if (!compact)
		{
			return offsetX;
		}

		if (manager.isAnchorRight() && !manager.getCurrentLayout().isCustom())
		{
			offsetX += manager.getCurrentLayout().getRightOffset();
		}

		return offsetX;
	}

	@Override
	public int yOffset(int y, boolean compact, OrbController manager, SlotManager slotManager)
	{
		offsetY = y;

		if (!compact)
		{
			return offsetY;
		}

		if (manager.isAnchorBottom() && !manager.getCurrentLayout().isCustom())
		{
			offsetY += manager.getCurrentLayout().getBottomOffset() - manager.clampVerticalY();
		}

		return offsetY;
	}

	@Override
	public int widthOffset(int w, boolean compact, OrbController manager, SlotManager slotManager)
	{
		offsetWidth = w;
		return offsetWidth;
	}

	@Override
	public int heightOffset(int h, boolean compact, OrbController manager, SlotManager slotManager)
	{
		offsetHeight = h;
		return offsetHeight;
	}

}

