	{
		if (!compactLayout)
		{
			return manager.isFixedMode() ? 83 : y;
		}

		if (manager.getCurrentLayout().isVertical())
		{
			y = slotManager.applyHiddenYOffset(Orbs.STORE_ORB_CONTAINER, y);
		}

		return y;
	}
}

