package com.interfacelayout.util;

import com.interfacelayout.layout.orbs.OrbLayout;
import lombok.Getter;

@Getter
public class SetValue
{
	private final int original;
	private final int[] modified;

	public SetValue(int original, int... modified)
	{
		this.original = original;
		this.modified = modified;
	}

	public SetValue(int original, int modified)
	{
		this.original = original;
		this.modified = new int[]{modified};
	}

	public int getModified(OrbLayout layout)
	{
		if (layout == null || modified.length == 0)
		{
			return original;
		}

		int index = layout.getIndex();

		return index < modified.length
			? modified[index]
			: modified[0];
	}
}

package com.interfacelayout.util;

import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetSizeMode;

/** Expands clipping ancestors, preserving the canvas positions of their native children. */
@Singleton
public class WidgetBoundsExpander
{
    @Inject private Client client;
    @Inject private WidgetStateStore states;
    private final Map<Widget, Boolean> expanded = new IdentityHashMap<>();

    public void clear() { expanded.clear(); }

    /** Only layers whose clipping bounds were actually enlarged in this layout. */
    public boolean isExpanded(int componentId)
    {
        return expanded.keySet().stream().anyMatch(widget -> widget.getId() == componentId);
    }

    public void allowCanvasPosition(Widget widget)
    {
        List<Widget> ancestors = new ArrayList<>();
        for (Widget parent = widget.getParent(); parent != null && ancestors.size() < 16; parent = parent.getParent())
        {
            ancestors.add(parent);
            Rectangle bounds = WidgetGeometry.bounds(parent);
            if (bounds.x == 0 && bounds.y == 0 && bounds.width >= client.getCanvasWidth()
                && bounds.height >= client.getCanvasHeight()) break;
        }
        Collections.reverse(ancestors);
        for (Widget parent : ancestors) expand(parent);
    }

    public void allowChildrenAcrossCanvas(Widget parent)
    {
        allowCanvasPosition(parent);
        expand(parent);
    }

    private void expand(Widget parent)
    {
        if (expanded.containsKey(parent)) return;
        Rectangle bounds = WidgetGeometry.bounds(parent);
        if (bounds.x == 0 && bounds.y == 0 && bounds.width >= client.getCanvasWidth()
            && bounds.height >= client.getCanvasHeight()) return;
        expanded.put(parent, true);
        Map<Widget, Point> positions = new IdentityHashMap<>();
        collect(parent.getStaticChildren(), positions);
        collect(parent.getDynamicChildren(), positions);
        collect(parent.getNestedChildren(), positions);
        // Freeze sibling sizes before changing their parent; MINUS-sized minimap layers
        // would otherwise grow to canvas size together with the clipping ancestor.
        positions.keySet().forEach(child -> {
            states.capture(child);
            int width = child.getWidth(), height = child.getHeight();
            child.setOriginalWidth(width); child.setOriginalHeight(height);
            child.setWidthMode(WidgetSizeMode.ABSOLUTE); child.setHeightMode(WidgetSizeMode.ABSOLUTE);
        });
        states.capture(parent);
        Widget grandparent = parent.getParent();
        Rectangle outer = WidgetGeometry.bounds(grandparent);
        states.position(parent, -outer.x, -outer.y);
        parent.setOriginalWidth(client.getCanvasWidth()); parent.setOriginalHeight(client.getCanvasHeight());
        parent.setWidthMode(WidgetSizeMode.ABSOLUTE); parent.setHeightMode(WidgetSizeMode.ABSOLUTE);
        // Expanding a layer must not create an invisible canvas-sized input blocker.
        parent.setNoClickThrough(false);
        parent.revalidate();
        Rectangle now = WidgetGeometry.bounds(parent);
        positions.forEach((child, canvas) -> {
            states.position(child, canvas.x - now.x, canvas.y - now.y);
            child.revalidate();
        });
    }

    private static void collect(Widget[] children, Map<Widget, Point> positions)
    {
        if (children == null) return;
        for (Widget child : children)
            if (child != null) positions.put(child, WidgetGeometry.location(child));
    }
}

package com.interfacelayout.util;

import java.awt.Point;
import java.awt.Rectangle;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import net.runelite.api.widgets.Widget;

/** Canvas coordinates from current layout values, independent of the last draw pass. */
public final class WidgetGeometry
{
    private WidgetGeometry() {}
    public static Point location(Widget widget)
    {
        Point point = new Point();
        Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
        for (Widget current = widget; current != null && visited.add(current); current = current.getParent())
        {
            point.translate(current.getRelativeX(), current.getRelativeY());
            Widget parent = current.getParent();
            if (parent != null) point.translate(-parent.getScrollX(), -parent.getScrollY());
        }
        return point;
    }
    public static Rectangle bounds(Widget widget)
    {
        if (widget == null) return new Rectangle();
        Point point = location(widget);
        return new Rectangle(point.x, point.y, widget.getWidth(), widget.getHeight());
    }
}

package com.interfacelayout.util;

import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Comparator;
import javax.inject.Singleton;
import net.runelite.api.widgets.Widget;
import net.runelite.api.Client;

/** Client-thread-only ownership journal. Never stores widgets in persistent config. */
@Singleton
public class WidgetStateStore
{
    private final Map<Widget, State> states = new IdentityHashMap<>();

    public void capture(Widget widget)
    {
        if (widget != null) states.computeIfAbsent(widget, State::new);
    }
    public void discardRetired(Client client)
    {
        states.keySet().removeIf(widget -> {
            Widget current = client.getWidget(widget.getId());
            if (current != null && widget.getIndex() >= 0) current = current.getChild(widget.getIndex());
            return current != widget;
        });
    }
    public void captureRendering(Widget widget)
    {
        capture(widget);
        if (widget != null) states.get(widget).captureRendering(widget);
    }
    public void captureOpacity(Widget widget)
    {
        capture(widget);
        if (widget != null && states.get(widget).opacity == null) states.get(widget).opacity = widget.getOpacity();
    }

    public void restoreRendering(Widget widget)
    {
        State state = states.get(widget);
        if (state != null) state.restoreRendering(widget);
    }

    public void hide(Widget widget, boolean hidden)
    {
        if (widget == null || !hidden) return;
        visibility(widget, true);
    }

    /** Undo only our own hiding; never reveal a component hidden by the game. */
    public void visibility(Widget widget, boolean hidden)
    {
        if (widget == null) return;
        if (!hidden)
        {
            State state = states.get(widget);
            if (state != null) state.restoreVisibility(widget);
            return;
        }
        capture(widget);
        State state = states.get(widget);
        if (state.hidden == null) state.hidden = widget.isSelfHidden();
        widget.setHidden(true);
    }

    /** Release visibility before native scripts, which may change the game's flags. */
    public void restoreVisibility()
    {
        states.forEach((widget, state) -> state.restoreVisibility(widget));
    }

    public boolean isHiddenByGame(Widget widget)
    {
        return isHiddenByGame(widget, null);
    }

    public boolean isHiddenByGame(Widget widget, WidgetStateStore other)
    {
        for (int depth = 0; widget != null && depth < 16; depth++, widget = widget.getParent())
        {
            State state = states.get(widget);
            State second = other == null ? null : other.states.get(widget);
            // Either journal may own our hiding (compact presets or Free Position).
            if (state != null && Boolean.FALSE.equals(state.hidden)
                || second != null && Boolean.FALSE.equals(second.hidden)) continue;
            boolean hidden = state != null && state.hidden != null ? state.hidden
                : second != null && second.hidden != null ? second.hidden : widget.isSelfHidden();
            if (hidden) return true;
        }
        return false;
    }

    public void position(Widget widget, int x, int y)
    {
        if (widget == null) return;
        capture(widget);
        widget.setForcedPosition(x, y);
    }

    public void restore()
    {
        // Restore dimensions first; then clear forced positions and revalidate descendants.
        states.forEach((widget, state) -> state.restore(widget));
        states.keySet().forEach(widget -> widget.setForcedPosition(-1, -1));
        states.keySet().stream().sorted(Comparator.comparingInt(WidgetStateStore::depth)).forEach(Widget::revalidate);
        states.clear();
    }

    private static int depth(Widget widget)
    {
        int depth = 0;
        for (Widget parent = widget.getParent(); parent != null && depth < 32; parent = parent.getParent()) depth++;
        return depth;
    }

    private static final class State
    {
        private final int x, y, xMode, yMode, width, height, widthMode, heightMode;
        private Integer opacity, type, contentType, sprite;
        private Boolean hidden;
        private final boolean noClickThrough;
        State(Widget widget)
        {
            width = widget.getOriginalWidth(); height = widget.getOriginalHeight();
            x = widget.getOriginalX(); y = widget.getOriginalY();
            xMode = widget.getXPositionMode(); yMode = widget.getYPositionMode();
            widthMode = widget.getWidthMode(); heightMode = widget.getHeightMode();
            noClickThrough = widget.getNoClickThrough();
        }
        void captureRendering(Widget widget)
        {
            if (type != null) return;
            type = widget.getType(); contentType = widget.getContentType(); sprite = widget.getSpriteId();
        }
        void restore(Widget widget)
        {
            widget.setOriginalWidth(width); widget.setOriginalHeight(height);
            widget.setOriginalX(x); widget.setOriginalY(y);
            widget.setXPositionMode(xMode); widget.setYPositionMode(yMode);
            widget.setWidthMode(widthMode); widget.setHeightMode(heightMode);
            if (opacity != null) widget.setOpacity(opacity);
            restoreRendering(widget);
            restoreVisibility(widget); widget.setNoClickThrough(noClickThrough);
        }
        void restoreVisibility(Widget widget)
        {
            if (hidden == null) return;
            widget.setHidden(hidden);
            hidden = null;
        }
        void restoreRendering(Widget widget)
        {
            if (type == null) return;
            widget.setType(type); widget.setContentType(contentType); widget.setSpriteId(sprite);
            type = null; contentType = null; sprite = null;
        }
    }
}

